// CSD_RATIONALE_BEGIN
// This strategy uses a combination of unconstrained and constrained steps to solve math word problems step by step. 
// In the unconstrained phase, it uses an unconstrained step to generate tokens. 
// Once it encounters "<<", it switches to the constrained phase where it uses a constrained step to ensure grammar validity.
// It also includes logic to handle repetition penalties and adjust temperature based on the number of expressions generated.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var insideConstrained: bool := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  invariant insideConstrained ==> forall t: Token :: t in parser.ValidNextTokens(currentConstrained) ==> t in lm.Tokens
  decreases maxSteps - steps, if insideConstrained then 1 else 0
{
  if !insideConstrained {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;
    if Contains(next, "<<") {
      insideConstrained := true;
      currentConstrained := [];
      CSDHelpers.RollbackPreservesTokenInvariant(lm, parser, []);
    }
  } else {
    if parser.IsCompletePrefix(currentConstrained) {
      insideConstrained := false;
    } else {
      var exprCount := CSDHelpers.CountSubstring(CSDHelpers.PrefixToString(generated), ">>");
      var next: Token;
      if exprCount >= 2 {
        next := helpers.RepetitionPenaltyStep(lm, parser, prompt, currentConstrained, generated, 3.0);
      } else {
        var count := helpers.ValidTokenCount(parser, currentConstrained);
        if count > 8 {
          next := helpers.TemperatureConstrainedStep(lm, parser, prompt, currentConstrained, 1.5);
        } else {
          next := helpers.TemperatureConstrainedStep(lm, parser, prompt, currentConstrained, 0.3);
        }
      }
      generated := generated + [next];
      currentConstrained := currentConstrained + [next];
      steps := steps + 1;
      if Contains(next, ">>") { insideConstrained := false; }
    }
  }
}
cost := helpers.cost;

